13	// runJetStreamEnv boots an embedded JetStream server with a stream bound to
14	// pub.> and returns a JetStream context for it.
15	func runJetStreamEnv(t *testing.T) jetstream.JetStream {
16		t.Helper()
17		s, err := natsserver.NewServer(&natsserver.Options{
18			Host:      "127.0.0.1",
19			Port:      -1, // pick a free port
20			NoLog:     true,
21			NoSigs:    true,
22			JetStream: true,
23			StoreDir:  t.TempDir(),
24		})
25		if err != nil {
26			t.Fatalf("new embedded nats server: %v", err)
27		}
28		go s.Start()
29		if !s.ReadyForConnections(10 * time.Second) {
30			t.Fatal("embedded nats server not ready in time")
31		}
32		t.Cleanup(s.Shutdown)
33	
34		nc, err := nats.Connect(s.ClientURL())
35		if err != nil {
36			t.Fatalf("connect: %v", err)
37		}
38		t.Cleanup(nc.Close)
39		js, err := jetstream.New(nc)
40		if err != nil {
41			t.Fatalf("jetstream.New: %v", err)
42		}
43		if _, err := js.CreateStream(context.Background(), jetstream.StreamConfig{
44			Name:       "pub_v1",
45			Subjects:   []string{"pub.>"},
46			Duplicates: time.Minute,
47		}); err != nil {
48			t.Fatalf("create stream: %v", err)
49		}
50		return js
51	}
52	
53	// TestPublisherStampsHeadersAndAcks drives the whole publish prologue: the
54	// stored message must carry the Nats-Msg-Id dedup key and the producer's
55	// injected trace context, and the ack must report the landing stream.
56	func TestPublisherStampsHeadersAndAcks(t *testing.T) {
57		js := runJetStreamEnv(t)
58		ctx, _, _ := remoteSpanCtx(t)
59	
60		p := Publisher{JS: js}
61		ack, err := p.Publish(ctx, &nats.Msg{Subject: "pub.repo", Data: []byte("payload")}, "msg-1")
62		if err != nil {
63			t.Fatalf("publish: %v", err)
64		}
65		if ack.Stream != "pub_v1" {
66			t.Errorf("ack stream = %q, want pub_v1", ack.Stream)
67		}
68		if ack.Duplicate {
69			t.Error("first publish reported as duplicate")
70		}
71	
72		stream, err := js.Stream(context.Background(), "pub_v1")
73		if err != nil {
74			t.Fatalf("bind stream: %v", err)
75		}
76		stored, err := stream.GetMsg(context.Background(), ack.Sequence)
77		if err != nil {
78			t.Fatalf("get stored msg: %v", err)
79		}
80		if got := stored.Header.Get(nats.MsgIdHdr); got != "msg-1" {
81			t.Errorf("stored Nats-Msg-Id = %q, want msg-1", got)
82		}
83		if got := stored.Header.Get("traceparent"); got == "" {
84			t.Error("stored message has no traceparent header; trace context was not injected")
85		}
86	}
87	
88	// TestPublisherDedupesByMsgID: a second publish with the same msg-id inside
89	// the duplicate window must be suppressed broker-side and reported as such —
90	// the normal outcome for an at-least-once producer retrying, not an error.
91	func TestPublisherDedupesByMsgID(t *testing.T) {
92		js := runJetStreamEnv(t)
93		p := Publisher{JS: js}
94	
95		first, err := p.Publish(context.Background(), &nats.Msg{Subject: "pub.repo", Data: []byte("x")}, "dup-1")
96		if err != nil {
97			t.Fatalf("first publish: %v", err)
98		}
99		second, err := p.Publish(context.Background(), &nats.Msg{Subject: "pub.repo", Data: []byte("x")}, "dup-1")
100		if err != nil {
101			t.Fatalf("second publish: %v", err)
102		}
103		if !second.Duplicate {
104			t.Error("second publish with the same msg-id not reported as duplicate")
105		}
106		if second.Sequence != first.Sequence {
107			t.Errorf("duplicate ack sequence = %d, want the original %d", second.Sequence, first.Sequence)
108		}
109	}
110	
111	// TestPublisherEmptyMsgIDLeavesHeader: an empty msgID must not clobber a
112	// Nats-Msg-Id the caller already set on the message.
113	func TestPublisherEmptyMsgIDLeavesHeader(t *testing.T) {
114		js := runJetStreamEnv(t)
115		p := Publisher{JS: js}
116	
117		msg := &nats.Msg{Subject: "pub.repo", Data: []byte("x"), Header: nats.Header{}}
118		msg.Header.Set(nats.MsgIdHdr, "preset-1")
119		ack, err := p.Publish(context.Background(), msg, "")
120		if err != nil {
121			t.Fatalf("publish: %v", err)
122		}
123		stream, err := js.Stream(context.Background(), "pub_v1")
124		if err != nil {
125			t.Fatalf("bind stream: %v", err)
126		}
127		stored, err := stream.GetMsg(context.Background(), ack.Sequence)
128		if err != nil {
129			t.Fatalf("get stored msg: %v", err)
130		}
131		if got := stored.Header.Get(nats.MsgIdHdr); got != "preset-1" {
132			t.Errorf("stored Nats-Msg-Id = %q, want the caller's preset-1", got)
133		}
134	}
135	
136	// TestPublisherErrorsOnUnboundSubject: a subject no stream listens on must
137	// surface as an error (the broker sends no ack), not hang past the bound.
138	func TestPublisherErrorsOnUnboundSubject(t *testing.T) {
139		js := runJetStreamEnv(t)
140		p := Publisher{JS: js, Timeout: 500 * time.Millisecond}
141	
142		start := time.Now()
143		if _, err := p.Publish(context.Background(), &nats.Msg{Subject: "unbound.subject", Data: []byte("x")}, "m"); err == nil {
144			t.Fatal("publish to an unbound subject succeeded, want error")
145		}
146		if elapsed := time.Since(start); elapsed > 5*time.Second {
147			t.Errorf("publish error took %v, want it bounded well under the default", elapsed)
148		}
149	}
