1	package backoff
2	
3	import (
4		"errors"
5		"math"
6		"testing"
7		"time"
8	
9		"github.com/nats-io/nats.go/jetstream"
10	
11		"github.com/entireio/go-nuts/natsmsg/natsmsgtest"
12	)
13	
14	const testDelay = 5 * time.Second
15	
16	func delivered(n uint64) *natsmsgtest.FakeMsg {
17		return &natsmsgtest.FakeMsg{Meta: &jetstream.MsgMetadata{NumDelivered: n}}
18	}
19	
20	// TestNakOrTermNaksBeforeExhaustion: a transient failure with deliveries left
21	// redelivers with the flat policy delay.
22	func TestNakOrTermNaksBeforeExhaustion(t *testing.T) {
23		p := Policy{NakDelay: testDelay, MaxDeliver: 5, TermOnExhaustion: true}
24		msg := delivered(4)
25	
26		got, err := p.NakOrTerm(msg)
27		if err != nil {
28			t.Fatalf("NakOrTerm: %v", err)
29		}
30		if got != OutcomeNak {
31			t.Errorf("outcome = %q, want nak", got)
32		}
33		if len(msg.NakDelays) != 1 || msg.NakDelays[0] != testDelay {
34			t.Errorf("NakDelays = %v, want one nak with the policy delay", msg.NakDelays)
35		}
36		if msg.Termed {
37			t.Error("termed before exhaustion")
38		}
39	}
40	
41	// TestNakOrTermTermsOnFinalDelivery pins the COR-762 fix: on the final delivery
42	// of a work-queue consumer (TermOnExhaustion), Term removes the message cleanly
43	// instead of a Nak the broker drops — which would orphan it un-acked until
44	// StreamMaxAge.
45	func TestNakOrTermTermsOnFinalDelivery(t *testing.T) {
46		p := Policy{NakDelay: testDelay, MaxDeliver: 5, TermOnExhaustion: true}
47		msg := delivered(5)
48	
49		got, err := p.NakOrTerm(msg)
50		if err != nil {
51			t.Fatalf("NakOrTerm: %v", err)
52		}
53		if got != OutcomeTerm {
54			t.Errorf("outcome = %q, want term", got)
55		}
56		if !msg.Termed {
57			t.Error("final delivery not termed")
58		}
59		if len(msg.NakDelays) != 0 {
60			t.Errorf("NakDelays = %v, want none on the term path", msg.NakDelays)
61		}
62	}
63	
64	// TestNakOrTermKeepsNakWithoutOptIn: without TermOnExhaustion the final
65	// delivery still Naks — streams whose max_age doubles as the retry backstop
66	// keep their existing posture.
67	func TestNakOrTermKeepsNakWithoutOptIn(t *testing.T) {
68		p := Policy{NakDelay: testDelay, MaxDeliver: 5}
69		msg := delivered(5)
70	
71		got, err := p.NakOrTerm(msg)
72		if err != nil {
73			t.Fatalf("NakOrTerm: %v", err)
74		}
75		if got != OutcomeNak {
76			t.Errorf("outcome = %q, want nak", got)
77		}
78		if msg.Termed {
79			t.Error("termed without the TermOnExhaustion opt-in")
80		}
81	}
82	
83	// TestNakOrTermMissingMetadataNaks: a message without JetStream metadata (a
84	// synthetic test message) reads as non-final — the safe default is another
85	// retry, never a Term.
86	func TestNakOrTermMissingMetadataNaks(t *testing.T) {
87		p := Policy{NakDelay: testDelay, MaxDeliver: 1, TermOnExhaustion: true}
88		msg := &natsmsgtest.FakeMsg{MetaErr: errors.New("no metadata")}
89	
90		got, err := p.NakOrTerm(msg)
91		if err != nil {
92			t.Fatalf("NakOrTerm: %v", err)
93		}
94		if got != OutcomeNak {
95			t.Errorf("outcome = %q, want nak", got)
96		}
97		if msg.Termed {
98			t.Error("termed a message whose delivery count is unknown")
99		}
100	}
101	
102	// TestNakOrTermZeroMaxDeliverNaks pins the zero-value guard: MaxDeliver left
103	// at 0 means unlimited redeliveries (the jetstream.ConsumerConfig semantics),
104	// so no delivery is final and a transient failure Naks — it must NOT read
105	// every delivery as final and Term on the first failure.
106	func TestNakOrTermZeroMaxDeliverNaks(t *testing.T) {
107		p := Policy{NakDelay: testDelay, TermOnExhaustion: true} // MaxDeliver unset
108		msg := delivered(1)
109	
110		got, err := p.NakOrTerm(msg)
111		if err != nil {
112			t.Fatalf("NakOrTerm: %v", err)
113		}
114		if got != OutcomeNak {
115			t.Errorf("outcome = %q, want nak", got)
116		}
117		if msg.Termed {
118			t.Error("termed on the first delivery with an unset MaxDeliver")
119		}
120	}
121	
122	// TestDelayForFlatByDefault pins zero-value compatibility: without a Factor
123	// the envelope stays flat at NakDelay for every delivery, exactly the
124	// pre-growth behavior.
125	func TestDelayForFlatByDefault(t *testing.T) {
126		p := Policy{NakDelay: testDelay}
127		for _, n := range []int{0, 1, 2, 5, 50} {
128			if got := p.DelayFor(n); got != testDelay {
129				t.Errorf("flat DelayFor(%d) = %v, want %v", n, got, testDelay)
130			}
131		}
132	}
133	
134	// TestDelayForGrows covers the two envelopes the services actually run:
135	// entire-api's 1s doubling capped at 300s and entiredb's 5s doubling capped
136	// at 30s.
137	func TestDelayForGrows(t *testing.T) {
138		for _, tc := range []struct {
139			name string
140			p    Policy
141			want map[int]time.Duration
142		}{
143			{
144				name: "1s doubling capped at 300s",
145				p:    Policy{NakDelay: time.Second, Factor: 2, MaxDelay: 300 * time.Second},
146				want: map[int]time.Duration{
147					0: time.Second, 1: time.Second, 2: 2 * time.Second, 3: 4 * time.Second,
148					9: 256 * time.Second, 10: 300 * time.Second, 20: 300 * time.Second,
149				},
150			},
151			{
152				name: "5s doubling capped at 30s",
153				p:    Policy{NakDelay: 5 * time.Second, Factor: 2, MaxDelay: 30 * time.Second},
154				want: map[int]time.Duration{
155					1: 5 * time.Second, 2: 10 * time.Second, 3: 20 * time.Second,
156					4: 30 * time.Second, 8: 30 * time.Second,
157				},
158			},
159		} {
160			for n, want := range tc.want {
161				if got := tc.p.DelayFor(n); got != want {
162					t.Errorf("%s: DelayFor(%d) = %v, want %v", tc.name, n, got, want)
163				}
164			}
165		}
166	}
167	
168	// TestDelayForSaturatesWithoutCap: uncapped growth must saturate rather than
169	// wrap negative — a negative NakWithDelay would redeliver immediately, the
170	// opposite of backing off.
171	func TestDelayForSaturatesWithoutCap(t *testing.T) {
172		p := Policy{NakDelay: time.Hour, Factor: 10}
173		if got := p.DelayFor(30); got != time.Duration(math.MaxInt64) {
174			t.Errorf("uncapped DelayFor(30) = %v, want saturation at MaxInt64", got)
175		}
176		if got := p.DelayFor(30); got < 0 {
177			t.Errorf("uncapped DelayFor(30) went negative: %v", got)
178		}
179	}
180	
181	// TestNakOrTermUsesGrownDelay: NakOrTerm must nak with the delay for THIS
182	// delivery's count from the message metadata, not the base delay.
183	func TestNakOrTermUsesGrownDelay(t *testing.T) {
184		p := Policy{NakDelay: time.Second, Factor: 2, MaxDelay: 300 * time.Second, MaxDeliver: 8}
185		msg := delivered(3)
186	
187		got, err := p.NakOrTerm(msg)
188		if err != nil {
189			t.Fatalf("NakOrTerm: %v", err)
190		}
191		if got != OutcomeNak {
192			t.Errorf("outcome = %q, want nak", got)
193		}
194		if len(msg.NakDelays) != 1 || msg.NakDelays[0] != 4*time.Second {
195			t.Errorf("NakDelays = %v, want one nak with the grown 4s delay", msg.NakDelays)
196		}
197	}
198	
199	// TestNakOrTermGrownDelayMissingMetadata: without metadata the delivery count
200	// is unknown; the policy naks with the base delay (first-delivery read).
201	func TestNakOrTermGrownDelayMissingMetadata(t *testing.T) {
202		p := Policy{NakDelay: time.Second, Factor: 2, MaxDelay: 300 * time.Second}
203		msg := &natsmsgtest.FakeMsg{MetaErr: errors.New("no metadata")}
204	
205		if _, err := p.NakOrTerm(msg); err != nil {
206			t.Fatalf("NakOrTerm: %v", err)
207		}
208		if len(msg.NakDelays) != 1 || msg.NakDelays[0] != time.Second {
209			t.Errorf("NakDelays = %v, want one nak with the base delay", msg.NakDelays)
210		}
211	}
212	
213	func TestNumDelivered(t *testing.T) {
214		if got := NumDelivered(delivered(3)); got != 3 {
215			t.Errorf("NumDelivered = %d, want 3", got)
216		}
217		if got := NumDelivered(&natsmsgtest.FakeMsg{MetaErr: errors.New("none")}); got != 0 {
218			t.Errorf("NumDelivered without metadata = %d, want 0", got)
219		}
220	}
221	
222	func TestIsFinalDelivery(t *testing.T) {
223		if IsFinalDelivery(delivered(4), 5) {
224			t.Error("delivery 4/5 read as final")
225		}
226		if !IsFinalDelivery(delivered(5), 5) {
227			t.Error("delivery 5/5 not read as final")
228		}
229		if !IsFinalDelivery(delivered(6), 5) {
230			t.Error("delivery past MaxDeliver not read as final")
231		}
232		if IsFinalDelivery(delivered(1), 0) {
233			t.Error("delivery read as final with MaxDeliver 0 (unlimited)")
234		}
235		if IsFinalDelivery(delivered(1), -1) {
236			t.Error("delivery read as final with MaxDeliver -1 (unlimited)")
237		}
238	}
