18	
19	type fakeJetStream struct {
20		lastMsg *nats.Msg
21		ack     *nats.PubAck
22		err     error
23		calls   int
24	}
25	
26	func (f *fakeJetStream) PublishMsg(m *nats.Msg, _ ...nats.PubOpt) (*nats.PubAck, error) {
27		f.calls++
28		f.lastMsg = m
29		if f.err != nil {
30			return nil, f.err
31		}
32		if f.ack != nil {
33			return f.ack, nil
34		}
35		return &nats.PubAck{Stream: "test_stream", Sequence: 1}, nil
36	}
37	
38	// withTracing installs a recording tracer provider + W3C propagator and
39	// returns the recorder plus a restore func.
40	func withTracing(t *testing.T) *tracetest.SpanRecorder {
41		t.Helper()
42		prevTP := otel.GetTracerProvider()
43		prevProp := otel.GetTextMapPropagator()
44	
45		rec := tracetest.NewSpanRecorder()
46		tp := sdktrace.NewTracerProvider(sdktrace.WithSpanProcessor(rec))
47		otel.SetTracerProvider(tp)
48		otel.SetTextMapPropagator(propagation.NewCompositeTextMapPropagator(
49			propagation.TraceContext{},
50			propagation.Baggage{},
51		))
52		t.Cleanup(func() {
53			_ = tp.Shutdown(context.Background())
54			otel.SetTracerProvider(prevTP)
55			otel.SetTextMapPropagator(prevProp)
56		})
57		return rec
58	}
59	
60	func testPublication(js *fakeJetStream) Publication {
61		return Publication{
62			Tracer:   "natspub-test",
63			SpanName: "test.publish",
64			ErrKind:  "test job",
65			LogMsg:   "Published test job",
66			Subject:  "test.v1.us.cluster",
67			MsgID:    "id-1",
68			Marshal:  func() ([]byte, error) { return []byte(`{"ok":true}`), nil },
69			SpanAttrs: append(PlacementAttrs("us", "cluster"),
70				attribute.Int64("entire.github_repo_id", 42)),
71		}
72	}
73	
74	func TestPublishSetsSubjectMsgIDAndPayload(t *testing.T) {
75		withTracing(t)
76	
77		js := &fakeJetStream{ack: &nats.PubAck{Sequence: 7, Duplicate: true}}
78		if err := Publish(context.Background(), js, testPublication(js)); err != nil {
79			t.Fatalf("Publish: %v", err)
80		}
81	
82		if js.calls != 1 {
83			t.Fatalf("calls = %d, want 1", js.calls)
84		}
85		if js.lastMsg.Subject != "test.v1.us.cluster" {
86			t.Errorf("Subject = %q, want test.v1.us.cluster", js.lastMsg.Subject)
87		}
88		if got := js.lastMsg.Header.Get(MsgIDHeader); got != "id-1" {
89			t.Errorf("Nats-Msg-Id = %q, want id-1", got)
90		}
91		if string(js.lastMsg.Data) != `{"ok":true}` {
92			t.Errorf("Data = %q, want {\"ok\":true}", js.lastMsg.Data)
93		}
94		if js.lastMsg.Header.Get("traceparent") == "" {
95			t.Error("traceparent header not injected")
96		}
97	}
