99	func TestPublishRecordsProducerSpan(t *testing.T) {
100		rec := withTracing(t)
101	
102		js := &fakeJetStream{ack: &nats.PubAck{Sequence: 7, Duplicate: true}}
103		if err := Publish(context.Background(), js, testPublication(js)); err != nil {
