304	// backoffFor returns a per-message delay that grows with redelivery
305	// count. Caps at 5 minutes — the consumer's MaxDeliver eventually
306	// kicks the message to the DLQ even on persistent failure.
307	func backoffFor(msg jetstream.Msg) time.Duration {
308		meta, err := msg.Metadata()
309		if err != nil {
310			return 5 * time.Second
311		}
312		// 1, 2, 4, 8, 16, 32, 64, 128, 256 seconds, then capped at 300s.
313		delivery := meta.NumDelivered
314		if delivery == 0 {
315			delivery = 1
316		}
317		d := time.Second
318		for i := uint64(1); i < delivery && d < 300*time.Second; i++ {
319			d *= 2
320		}
321		if d > 300*time.Second {
322			d = 300 * time.Second
323		}
324		return d
325	}
